package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.std.NumberSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class NumberSerializer_acceptJsonFormatVisitor_TriageGen0Test {

    private JsonFormatVisitorWrapper visitor;
    private JavaType typeHint;

    @Before
    public void setUp() {
        visitor = mock(JsonFormatVisitorWrapper.class);
        typeHint = mock(JavaType.class);
    }

    /**
     * Test Case 1: _isInt is true.
     * Should call visitIntFormat with BIG_INTEGER.
     * Note: Since visitIntFormat is a protected method in the same class, 
     * we test the side effect via the visitor if possible, 
     * but since visitIntFormat calls visitor.expectIntFormat, we verify that.
     */
    @Test
    public void testAcceptJsonFormatVisitor_isIntTrue() throws JsonMappingException {
        // We use a subclass or a spy to trigger the _isInt branch if it were accessible, 
        // but since it's a private field in the real class, we rely on the constructor 
        // or the fact that NumberSerializer is designed to handle specific types.
        // For Integer/Long, _isInt is usually true.

        NumberSerializer serializer = new NumberSerializer(Integer.class);

        // Since we cannot directly set _isInt via constructor for all cases in some Jackson versions,
        // we assume the constructor for Integer.class sets _isInt to true.

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // visitIntFormat internally calls visitor.expectIntFormat
        verify(visitor).expectIntFormat(typeHint);
    }

    /**
     * Test Case 2: _isInt is false AND handledType is BigDecimal.
     * Should call visitFloatFormat with BIG_DECIMAL.
     */
    @Test
    public void testAcceptJsonFormatVisitor_isNotInt_isBigDecimal() throws JsonMappingException {
        // BigDecimal is not an integer type, so _isInt will be false.
        NumberSerializer serializer = new NumberSerializer(BigDecimal.class);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // visitFloatFormat internally calls visitor.expectFloatFormat
        verify(visitor).expectFloatFormat(typeHint, JsonParser.NumberType.BIG_DECIMAL);
    }

    /**
     * Test Case 3: _isInt is false AND handledType is NOT BigDecimal (e.g., Double).
     * Should call visitor.expectNumberFormat(typeHint).
     */
    @Test
    public void testAcceptJsonFormatVisitor_isNotInt_isNotBigDecimal() throws JsonMappingException {
        // Double is not an integer type, and is not BigDecimal.
        NumberSerializer serializer = new NumberSerializer(Double.class);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Should fall through to the else block: visitor.expectNumberFormat(typeHint)
        verify(visitor).expectNumberFormat(typeHint);
    }

    /**
     * Test Case 4: Verify exception propagation.
     */
    @Test(expected = JsonMappingException.class)
    public void testAcceptJsonFormatVisitor_throwsException() throws JsonMappingException {
        NumberSerializer serializer = new NumberSerializer(Double.class);

        // Setup mock to throw exception
        when(visitor.expectNumberFormat(any(JavaType.class))).thenThrow(new JsonMappingException(null, "Mock Error"));

        serializer.acceptJsonFormatVisitor(visitor, typeHint);
    }
}
